effect.shader:
const int TAPS = 24;
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = max(src.a, 1e-4);
  vec3 c = src.rgb / a;
  vec2 light = vec2(centerX, centerY);
  vec2 delta = (uv - light) / float(TAPS);
  vec2 p = uv;
  float w = 1.0;
  vec3 acc = vec3(0.0);
  for (int i = 0; i < TAPS; i++){
    p -= delta;
    vec4 s = texture2DCv(inputImg.texture, p);
    acc += (s.rgb / max(s.a, 1e-4)) * w;
    w *= decay;
  }
  acc /= float(TAPS);
  vec3 col = c + acc * rayColor.rgb * intensity * mixAmt;
  gl_FragColor = vec4(clamp(col, 0.0, 1.0) * a, a);
}
